-- Backfill orphan historical result IDs before FK
insert into public.requirement_definitions (
  id, original_name, display_name, category, sub_category, requirement_type, sort_order, handler_key, manual_instructions, source_section
)
select distinct
  r.requirement_id, r.requirement_name, r.requirement_name,
  coalesce(r.requirement_category, 'Unknown'), coalesce(r.requirement_sub_category, ''),
  r.requirement_type::public.requirement_definition_type, 9999,
  coalesce(r.handler_used, 'manualRequirementHandler'),
  'Imported from historical scan result snapshot.', coalesce(r.requirement_sub_category, '')
from public.requirement_check_results r
where not exists (select 1 from public.requirement_definitions d where d.id = r.requirement_id)
on conflict (id) do nothing;

do $$
begin
  if not exists (
    select 1 from pg_constraint
    where conname = 'requirement_check_results_requirement_id_fkey'
      and conrelid = 'public.requirement_check_results'::regclass
  ) then
    alter table public.requirement_check_results
      add constraint requirement_check_results_requirement_id_fkey
      foreign key (requirement_id) references public.requirement_definitions (id) on update cascade;
  end if;
end $$;
